      options: { layout: { padding: { top: 20 } }, plugins: { legend: { display: false }, tooltip: { callbacks: { label: function (c) { return c.dataIndex === 2 ? 'typically 10–20% insured' : c.raw + '% insured'; } } } }, scales: { x: axis({ grid: false }), y: Object.assign(axis({ title: '% of economic losses insured' }), { min: 0, max: 100 }) } },
