      setText('s-freq-o', '×' + freq.toFixed(2).replace(/0$/, '')); setText('s-perm-o', Math.round(perm * 100) + '%'); setText('s-catch-o', '+' + catchu.toFixed(2).replace(/0$/, '') + ' pp'); setText('s-warn-o', Math.round(warn * 100) + '%'); setText('s-fin-o', Math.round(fin * 100) + '%'); setText('s-inf-o', Math.round(inf * 100) + '%');
